           public void waitAtConsole() {
                mutex.acquire();
                AtConsoleCount++;

                if (AtConsoleCount == 4) {
                    state = CONSOLE_ALLOW;
                    cv.broadcast(); // Allow all four to proceed
                } else {
                    while (state != CONSOLE_ALLOW) {
                        cv.wait(mutex); // Wait until CONSOLE_ALLOW state
                    }
